import {VERSION,BALANCE as B,AREAS,SPECIES,ITEMS,RECIPES,SKILLS,ABILITIES,PASSIVES,ELEMENTS,QUALITIES,RAIDS,skillXP,feralXP,levelFor} from './data.mjs';
import * as E from './engine.mjs';
import * as Saves from './saves.mjs';
import * as Net from './online.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.floor(n||0).toLocaleString(),short=n=>n>=1e6?(n/1e6).toFixed(1)+'m':n>=10000?(n/1000).toFixed(1)+'k':fmt(n);
const duration=n=>n>=3600?`${Math.floor(n/3600)}h ${Math.floor(n%3600/60)}m`:n>=60?`${Math.floor(n/60)}m ${Math.floor(n%60)}s`:`${Math.ceil(n)}s`;
let loaded=Saves.load(),s=loaded.state,view='battle',skill='logging',bagTab='all',collectionArea='all',collectionMode='owned',selectedStarter=0,busy=false,tabLocked=false,lastPerformance=performance.now(),accumulator=0,lastSave=0,lastRender=0,cloudElapsed=0,cloudBusy=false,marketRows=[],leaderRows=[];
const nav=[['battle','⚔','Battle'],['skills','⚒','Skills'],['ferals','♧','Ferals'],['bag','▣','Inventory'],['world','◇','World'],['raids','♜','Raids'],['social','⚖','Trading post'],['journal','☷','Journal'],['settings','⚙','Settings']];
const portrait=(id,cls='',extra='')=>{const cell=id%50;return `<div class="portrait ${cls}" style="background-image:url('ferals-${id<50?'a':'b'}.png');background-position:${cell%5*25}% ${Math.floor(cell/5)*100/9}%" role="img" aria-label="${esc(SPECIES[id].name)}" ${extra}></div>`;};
const bar=(value,cls='',attr='')=>`<div class="progress ${cls}"><i style="width:${Math.max(0,Math.min(100,value))}%" ${attr}></i></div>`;
const btn=(text,action,args='',cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" ${args} ${disabled?'disabled':''}>${text}</button>`;
const header=(title,description,action='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const itemIcon=id=>({material:'◈',equipment:'⛨',snare:'⌘',food:'♨',treat:'♡',revive:'✚',appraise:'◎',lure:'✧',key:'⚿',automation:'⌁'}[ITEMS[id]?.type]||'◈');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function modal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('✕','close','aria-label="Close dialog"','subtle')}</div><div class="modal-body">${html}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function persist(){if(!s||tabLocked)return;try{s.lastWall=Date.now();Saves.save(s);$('#save-status')?.replaceChildren(document.createTextNode(Net.online.connected?Net.online.status:'Saved on this device'));}catch(e){toast('Save failed. Export a backup in Settings now.');console.error(e);}}
function activityHTML(){const a=s.activity;let name='Trainer supporting combat',text=s.boost?.until>s.clock?s.boost.element+' hunting boost · '+duration((s.boost.until-s.clock)/1000):'Auto-eat and capture support available',progress=0;if(s.trainer!=='combat'){name=a?SKILLS[a.skill].name+' · '+(a.recipe?ITEMS[a.recipe].name:AREAS[a.tier].materials[{logging:0,mining:1,fishing:2,foraging:3}[a.skill]]):'Trainer resting';text=s.combat?'Team fighting independently · no food or captures':a?'Trainer working · team resting':'Choose a skill or join your team';if(a)progress=a.progress/(a.recipe?RECIPES.find(r=>r.id===a.recipe).seconds:5+a.tier*.6)*100;}return `<div class="activity-strip"><span class="activity-icon">${s.trainer==='combat'?'⚔':a?SKILLS[a.skill].icon:'☽'}</span><div><strong>${name}</strong> <small class="gold" id="activity-countdown"></small><small style="display:block">${text}</small>${bar(progress,'','id="activity-progress"')}</div>${btn(s.trainer==='combat'?'Assign skill':'Join team',s.trainer==='combat'?'nav':'join',s.trainer==='combat'?'data-view="skills"':'','subtle')}</div>`;}
function render(){if(!s){$('#app').innerHTML=`<main class="onboarding"><h1>Your save needs attention</h1><p>${esc(loaded.error)}</p><p>Your existing save has been preserved. Import an exported backup to recover.</p><label>Restore backup<input type="file" id="import-save" accept=".json"></label></main>`;return;}if(!s.started)return onboarding();document.body.classList.toggle('no-motion',!s.settings.motion);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>FERALWILD<small>THE UNTAMED IDLE RPG</small></div></div><div><div class="side-label" style="margin:0 12px 12px">Your journey</div><nav class="side-nav">${nav.map(([id,icon,name])=>btn(`<span class="nav-icon">${icon}</span>${name}`,'nav',`data-view="${id}"`,view===id?'active':'')).join('')}</nav></div><div class="side-footer"><strong style="font-size:.85rem">${esc(s.name)}</strong><small>${s.badges.length} badges · Feral level cap ${E.cap(s)}</small><small id="save-status">${Net.online.connected?Net.online.status:'Saved on this device'}</small><small>Feralwild v${VERSION}</small></div></aside><main class="main"><header class="topbar"><div class="brand"><img src="icon.svg" alt=""><div>FERALWILD<small>WANDER. DISCOVER. BELONG.</small></div></div><div class="top-stats"><div class="top-stat gold">◈ <strong data-gold>${short(s.gold)}</strong><small>GOLD</small></div><div class="top-stat">◇ <strong>${s.badges.length}/10</strong><small>BADGES</small></div>${btn(`<span class="avatar">${esc(s.name[0].toUpperCase())}</span>`,'account','aria-label="Account"','account-chip')}</div></header><div class="page">${activityHTML()}${page()}</div></main><nav class="mobile-nav">${[nav[0],nav[1],nav[2],nav[3],['more','☰','More']].map(([id,icon,name])=>btn(`<span class="nav-icon">${icon}</span>${name}`,id==='more'?'more':'nav',`data-view="${id}"`,view===id||(id==='more'&&!['battle','skills','ferals','bag'].includes(view))?'active':'')).join('')}</nav></div>`;updateLive();}
function onboarding(){const picks=[0,1,6];$('#app').innerHTML=`<main class="onboarding"><div class="brand"><img src="icon.svg" alt=""><div>FERALWILD<small>THE UNTAMED IDLE RPG</small></div></div><div class="intro"><span class="eyebrow">Every great journey begins with a companion</span><h1>Who will walk beside you?</h1><p>Explore the wild. Build your team. Find the one in twelve thousand.</p></div><div class="three">${picks.map(id=>{const sp=SPECIES[id];return `<button class="starter ${selectedStarter===id?'selected':''}" data-action="starter" data-id="${id}" aria-pressed="${selectedStarter===id}">${portrait(id)}<div class="info"><span class="eyebrow">${sp.style}</span><h2>${sp.name}</h2><p>${id===0?'Quick, sharp, and always first into the undergrowth. A precise attacker.':id===1?'A living shelter of moss and stone. Draws attacks away from allies.':'A little light with a stubborn heart. Drains enemies to sustain itself.'}</p><small>${ABILITIES[sp.ability].name} · ${PASSIVES[sp.passive].name}</small></div></button>`;}).join('')}</div><div class="starter-form"><label>Your trainer name<input id="trainer-name" maxlength="24" placeholder="Wanderer" autocomplete="nickname" value="${esc(s.name==='Wanderer'?'':s.name)}"></label>${btn('Begin your journey →','begin','','primary wide')}${btn('Already have a cloud save? Sign in','account','','subtle wide')}<small class="small">Your starter has fixed 60 IVs. Every wild Feral rolls independently.<br>Local saves work without an account. Feralwild v${VERSION}</small></div></main>`;}
function page(){return ({battle:battlePage,skills:skillsPage,ferals:feralsPage,bag:bagPage,world:worldPage,raids:raidsPage,social:socialPage,journal:journalPage,settings:settingsPage}[view]||battlePage)();}
function fighter(f,enemy=false){const sp=SPECIES[f.species],st=E.stats(s,f),level=enemy?f.level:E.feralLevel(s,f);return `<article class="fighter ${enemy?'enemy':''} ${f.hp<=0?'down':''} ${s.combat?.focus===f.id?'targeted':''}" data-fighter="${f.id}"><div class="hit-layer"></div>${portrait(f.species,'',enemy?`data-action="focus" data-id="${f.id}" tabindex="0" aria-label="Target ${sp.name}"`:`data-action="detail" data-id="${f.id}" tabindex="0"`)}<span class="style-chip">${sp.style==='Melee'?'⚔':sp.style==='Ranged'?'➶':'✧'} ${sp.style}</span><span class="element-chip">${f.titan?'♛ ':''}${f.element||''}</span><div class="fighter-meta"><div class="fighter-name">${sp.name}</div><small>Lv. ${level} · <span class="rarity ${sp.rarity}">${sp.rarity}</span></small><div class="hp-line"><span>HP</span><span data-hp="${f.id}">${Math.ceil(f.hp)} / ${st.hp}</span></div>${bar(f.hp/st.hp*100,'',`data-health="${f.id}"`)}${bar(f.timer/st.interval*100,'attack-bar',`data-timer="${f.id}"`)}<div class="statusline" data-status="${f.id}">${ABILITIES[sp.ability].name} · ${Math.ceil(f.cooldown)}s</div>${enemy&&s.combat.kind==='wild'?btn(`Snare · ${Math.round(E.captureChance(s,f)*100)}%`,'capture',`data-id="${f.id}" data-capture="${f.id}"`,'capture-btn',s.trainer!=='combat'||f.hp<=0||!E.quantity(s,s.snare)||s.captureTimer>0):''}</div></article>`;}
function battlePage(){const a=AREAS[s.area],c=s.combat,team=E.ownedTeam(s),alive=team.some(f=>f.hp>0);return `${header('Into the wild','Your next extraordinary companion is out there.',btn('◇ Regions','nav','data-view="world"','subtle'))}<div class="split"><div class="panel"><div class="region-banner"><div class="row between"><span class="eyebrow">REGION ${String(a.id+1).padStart(2,'0')} · LV. ${a.level}–${Math.min(100,a.level+9)}</span><span class="badge">${c?c.kind==='wild'?'HUNTING':c.kind.toUpperCase():'AT REST'}</span></div><h2>${c?.kind==='raid'?RAIDS[c.raid].name:a.name}</h2><p>${c?.kind==='champion'?`Challenge: ${a.champion}`:c?.kind==='raid'?RAIDS[c.raid].stages[c.stage]:a.subtitle}</p></div><div class="battle-stage"><div class="battle-label"><span>${c?.kind==='raid'?'Raid encounter':'Wild encounters'}</span><span>${c?.kind==='wild'?`${c.kills} wins this hunt`:c?.kind==='champion'?'BADGE CHALLENGE':'MELEE → RANGED → MAGIC → MELEE'}</span></div><div id="enemy-row" class="combat-row enemy">${c?.enemies.length?c.enemies.map(f=>fighter(f,true)).join(''):`<div class="empty" style="width:100%"><span class="empty-icon">◇</span><h3>${alive?'The trail is yours to choose':'Your companions need care'}</h3><p style="font-size:.82rem">${alive?'Start a hunt to encounter the ten native species.':'Use crafted restorative medicine in your Feral collection.'}</p>${btn(alive?'Begin hunting':'Care for team',alive?'hunt':'nav',alive?'':'data-view="ferals"','primary')}</div>`}</div><div class="versus">${c?.respawn?'NEXT ENCOUNTER':'YOUR COMPANIONS'}</div><div class="combat-row" id="team-row">${team.map(f=>fighter(f)).join('')}${Array.from({length:3-team.length},()=>`<button class="team-empty" data-action="nav" data-view="ferals"><span>＋</span>Team slot<br><small>Capture a companion</small></button>`).join('')}</div></div><div class="combat-actions"><div id="raid-warning">${c?.cast?'<div class="battle-notice">Devastating attack charging — interrupt or guard!</div>':''}</div>${c?.awaiting?`<div class="battle-notice">Stage cleared. Choose your next approach.</div><div class="toolbar">${btn('Heal 40% · 500g','raid-choice','data-id="restore"')}${btn('12s Guard','raid-choice','data-id="ward"')}${btn('12s Haste','raid-choice','data-id="haste"')}</div>`:''}<div class="toolbar">${c?btn('Retreat','retreat','','danger'):btn('Start hunt','hunt','','primary',!alive)}${btn(s.hold?'Resume attacks':'Hold attacks','hold','','',!c)}${btn('Guard · 24s CD','command','data-id="guard"','',!c||s.trainer!=='combat')}${c?.kind==='raid'?btn('Interrupt','command','data-id="interrupt"'):''}</div><div class="two"><label>Capture snare<select id="snare-select">${Object.values(ITEMS).filter(i=>i.type==='snare').map(i=>`<option value="${i.id}" ${s.snare===i.id?'selected':''}>${i.name} (${E.quantity(s,i.id)})</option>`).join('')}</select></label><label>Auto-eat food<select id="food-select">${Object.values(ITEMS).filter(i=>i.type==='food').map(i=>`<option value="${i.id}" ${s.food===i.id?'selected':''}>${i.name} (${E.quantity(s,i.id)})</option>`).join('')}</select></label></div><label class="row" style="display:flex"><input type="checkbox" id="auto-eat" ${s.autoEat?'checked':''}> Auto-eat below 45% HP · trainer required</label><small>Tap a foe to focus fire. Hold attacks to weaken and capture safely; enemies keep attacking. Capture brings a Feral into your care at level 1 with its rolled traits intact.</small></div></div><div class="stack" style="align-content:start"><div class="panel"><div class="panel-head"><h3>Your next badge</h3><span class="badge gold">CAP ${E.cap(s)}</span></div><div class="panel-pad"><div class="row between"><strong>${a.champion}</strong><span class="muted">◇</span></div><small>${a.badge}</small>${tasksHTML(a)}<div style="margin-top:16px">${btn(s.badges.includes(a.id)?'Badge earned':'Challenge Champion','champion','','primary wide',s.badges.includes(a.id)||!E.tasks(s,a).every(t=>t.done)||!!c)}</div></div></div><div class="panel"><div class="panel-head"><h3>Field journal</h3>${btn('View all','nav','data-view="journal"','subtle')}</div><div id="recent-log">${logHTML(5)}</div></div><div class="muted-note"><strong class="gold">An extraordinary roll</strong><br>Titanblood chance: 1 in 12,000. Elemental chance: 1 in 180. Rarity never determines IV quality. Your next Common could be exceptional.</div></div></div>`;}
function tasksHTML(a){return E.tasks(s,a).map(t=>`<div class="task"><div class="row between"><span>${t.done?'<span class="check">✓</span> ':''}${t.name}</span><small>${t.current}/${t.goal}</small></div>${bar(t.current/t.goal*100)}${t.donation&&!t.done?btn('Donate herbs','donate',`data-id="${a.id}"`,'subtle',E.quantity(s,'herb'+a.id)<a.donation):''}</div>`).join('');}
function logHTML(n=100,rare=false){const rows=s.log.filter(l=>!rare||l.rare).slice(0,n);return rows.length?rows.map(l=>`<div class="log-row ${l.rare?'rare':''}"><time>${new Date(l.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><span>${esc(l.text)}</span></div>`).join(''):'<div class="empty"><p>Your encounters and milestones will be recorded here.</p></div>';}
function skillsPage(){const sk=SKILLS[skill],level=E.lv(s,skill),xp=s.skills[skill];return `${header('The working life','Every resource has a purpose. Every level opens a path.')}<div class="stack"><div class="skill-grid">${Object.entries(SKILLS).map(([id,k])=>`<button class="skill-card ${skill===id?'selected':''}" data-action="skill" data-id="${id}"><span class="skill-icon">${k.icon}</span><span>${k.name}</span><small>Level <strong data-skill-level="${id}">${E.lv(s,id)}</strong> / 100</small>${bar((s.skills[id]-skillXP(E.lv(s,id)))/(skillXP(Math.min(100,E.lv(s,id)+1))-skillXP(E.lv(s,id))||1)*100,'gold')}</button>`).join('')}</div><div class="panel"><div class="panel-head"><div><h2>${sk.icon} ${sk.name}</h2><small>${sk.description}</small></div><span class="badge gold" id="skill-level">LV. ${level}</span></div><div class="panel-pad"><div class="row between"><small id="skill-xp">${fmt(xp)} / ${level===100?'MAX':fmt(skillXP(level+1))} XP</small><small>${s.trainer===skill?'TRAINING':'READY'}</small></div><div style="margin-top:8px">${bar(level===100?100:(xp-skillXP(level))/(skillXP(level+1)-skillXP(level))*100,'gold','id="skill-progress"')}</div></div>${sk.type==='gather'?AREAS.map(a=>{const kind={logging:'log',mining:'ore',fishing:'fish',foraging:'herb'}[skill],item=ITEMS[kind+a.id],locked=level<a.level||a.id>s.badges.length;return `<div class="recipe-row ${locked?'locked':''}"><div class="row"><span class="item-mark">${sk.icon}</span><div><h3>${item.name}</h3><div class="cost">${a.name} · Lv. ${a.level}<br>${(5+a.id*.6).toFixed(1)}s · ${12+a.id*10} XP · Owned <span data-count="${item.id}">${fmt(E.quantity(s,item.id))}</span>${skill==='foraging'?' · + Wild fiber':''}</div></div></div>${btn(s.activity?.skill===skill&&s.activity?.tier===a.id?'Gathering':'Gather','gather',`data-id="${a.id}"`,'',locked)}</div>`;}).join(''):RECIPES.filter(r=>r.skill===skill).map(r=>{const item=ITEMS[r.id],locked=level<r.level||r.tier>s.badges.length;return `<div class="recipe-row ${locked?'locked':''}"><div><div class="row"><span class="item-mark">${itemIcon(r.id)}</span><div><h3>${item.name}</h3><small>Lv. ${r.level} · ${r.seconds}s · ${r.xp} XP${r.gold?' · '+fmt(r.gold)+'g':''}</small></div></div><div class="cost">${Object.entries(r.cost).map(([id,n])=>`${ITEMS[id].name} <span data-cost="${id}" data-need="${n}" style="color:${E.quantity(s,id)>=n?'var(--green)':'var(--red)'}">${fmt(E.quantity(s,id))}/${n}</span>`).join(' · ')}</div><small>${item.type==='equipment'?`${item.slot.toUpperCase()} · ${item.propertyText}`:item.heal?(item.type==='revive'?'Restore '+Math.round(item.heal*100)+'% HP after incapacitation':'Heal '+item.heal+' HP'):item.morale?'Restore '+item.morale+' Morale':item.type==='snare'?item.strength.toFixed(2)+'× capture strength':item.type==='lure'?'30 minutes of targeted hunting':item.type==='appraise'?'Permanently reveals exact IVs':''}</small></div>${btn(s.activity?.recipe===r.id?'Crafting':'Craft','craft',`data-id="${r.id}" data-recipe="${r.id}"`,'',locked||!E.canCraft(s,r))}</div>`;}).join('')}</div>${sk.type==='craft'?`<div class="muted-note">Crafting repeats until resources run out. Smithing rolls equipment quality from Poor to Legendary. Level 100 gives about a 5% Legendary chance; salvage returns only a fraction of invested materials.</div>`:''}</div>`;}
function feralsPage(){let ferals=s.ferals.filter(f=>collectionArea==='all'||SPECIES[f.species].area===Number(collectionArea));const species=SPECIES.filter(sp=>collectionArea==='all'||sp.area===Number(collectionArea));return `${header('Your companions',`${s.ferals.length} / ${s.storage} homes · ${Object.keys(s.caught).length} / 100 species captured`,btn('＋ Homes','storage','','subtle'))}<div class="tabs">${btn('My Ferals','collection-mode','data-id="owned"',collectionMode==='owned'?'active':'')}${btn('Compendium','collection-mode','data-id="dex"',collectionMode==='dex'?'active':'')}${btn('Research rewards','research','','')}</div><label style="margin-bottom:18px">Region<select id="collection-area"><option value="all">All regions</option>${AREAS.map(a=>`<option value="${a.id}" ${String(a.id)===collectionArea?'selected':''}>${a.name}</option>`).join('')}</select></label><div class="feral-grid">${collectionMode==='owned'?ferals.map(f=>{const sp=SPECIES[f.species];return `<button class="feral-card" data-action="detail" data-id="${f.id}">${portrait(f.species)}<div class="info"><div class="row between"><span class="rarity ${sp.rarity}">${sp.rarity} · ${sp.style}</span>${s.team.includes(f.id)?'<span class="badge">TEAM</span>':''}</div><h3>${sp.name} ${f.titan?'♛':''}</h3><small>Lv. ${E.feralLevel(s,f)}${f.element?' · '+f.element:''}${f.hp<=0?' · INCAPACITATED':''}</small><div class="row between"><small>Morale ${Math.round(f.morale)}%</small><small class="bond">♡ ${Math.floor(f.bond/100)}%</small></div>${bar(f.morale)}</div></button>`;}).join(''):species.map(sp=>`<button class="feral-card" data-action="species" data-id="${sp.id}">${portrait(sp.id)}<div class="info"><span class="rarity ${sp.rarity}">${sp.rarity} · ${sp.style}</span><h3>${sp.name}</h3><small>${s.caught[sp.id]?'✓ Captured '+s.caught[sp.id]:s.seen[sp.id]?'Seen '+s.seen[sp.id]:'Undiscovered'}</small></div></button>`).join('')}</div>${collectionMode==='owned'&&!ferals.length?'<div class="empty"><p>No companions from this region yet.</p></div>':''}`;}
function bagPage(){const rows=Object.entries(s.bag).filter(([id,n])=>n>0&&(bagTab==='all'||ITEMS[id].type===bagTab));const gear=bagTab==='all'||bagTab==='equipment'?s.gear:[];return `${header('Your inventory','Only what you own. Put every hard-earned resource to work.')}<div class="tabs">${[['all','Everything'],['material','Materials'],['equipment','Equipment'],['snare','Snares'],['food','Food'],['treat','Care'],['revive','Medicine'],['lure','Lures'],['key','Keys']].map(([id,n])=>btn(n,'bag-tab',`data-id="${id}"`,bagTab===id?'active':'')).join('')}</div><div class="inventory-grid">${rows.map(([id,n])=>`<div class="panel inventory-item"><div class="row"><span class="item-mark">${itemIcon(id)}</span><div><h3>${ITEMS[id].name}</h3><small>${ITEMS[id].type} · <strong data-count="${id}">${fmt(n)}</strong> owned</small></div></div><div class="toolbar">${['food','treat','revive','appraise'].includes(ITEMS[id].type)?btn('Use','use-picker',`data-id="${id}"`):ITEMS[id].type==='lure'?btn('Activate','lure',`data-id="${id}"`):''}${ITEMS[id].value?btn('Sell','sell-dialog',`data-id="${id}"`,'subtle'):''}</div></div>`).join('')}${gear.map(g=>`<div class="panel inventory-item"><div class="row"><span class="item-mark">⛨</span><div><h3 class="quality-${g.quality}">${ITEMS[g.item].name}</h3><small>${QUALITIES[g.quality]} · ${ITEMS[g.item].slot}</small></div></div><small>${ITEMS[g.item].propertyText}</small>${btn('Inspect / equip','gear-detail',`data-id="${g.id}"`,'subtle')}</div>`).join('')}</div>${!rows.length&&!gear.length?'<div class="panel empty"><span class="empty-icon">▣</span><h3>Your next project starts here</h3><p>Gather resources or craft supplies to fill this section.</p></div>':''}`;}
function worldPage(){return `${header('Beyond the treeline','Ten regions. Ten Champions. One long journey.')}<div class="area-grid">${AREAS.map(a=>{const unlocked=a.id<=s.badges.length;return `<div class="panel area-card ${unlocked?'':'locked'}" style="--area:${a.color}"><div class="row between"><div class="row"><span class="number">${String(a.id+1).padStart(2,'0')}</span><div><h2>${a.name}</h2><small>${a.subtitle}</small></div></div></div><div class="row between"><span class="badge ${s.badges.includes(a.id)?'gold':''}">${s.badges.includes(a.id)?'✓ '+a.badge:unlocked?'OPEN':AREAS[a.id-1].badge+' required'}</span><small>Lv. ${a.level}–${Math.min(100,a.level+9)}</small></div><small>${a.champion} · ${a.names.filter((_,j)=>s.caught[a.id*10+j]).length}/10 natives captured</small>${btn(s.area===a.id?'Current region':'Travel here','travel',`data-id="${a.id}"`,s.area===a.id?'subtle':'',!unlocked||!!s.combat)}</div>`;}).join('')}</div><div class="muted-note" style="margin-top:16px">Retreat before traveling. Badges raise Feral level caps by 10; the ninth badge unlocks level 100. The final Champion guards endgame prestige and the First Wild raid.</div>`;}
function raidsPage(){return `${header('The old powers','Bring a prepared team. These fights need your attention.')}<div class="stack">${RAIDS.map(r=>`<div class="panel"><div class="panel-head"><div><span class="eyebrow">ENDGAME RAID · ${r.badge} BADGES</span><h2 style="margin-top:7px">${r.name}</h2></div><span class="badge gold">${s.raidWins[r.id]} WINS</span></div><div class="panel-pad"><div class="detail-hero">${portrait(r.species)}<div><h3>${r.boss}</h3><p style="font-size:.85rem;margin-top:8px">Three stages. Interrupt charged attacks, guard your team, and choose a boon between encounters.</p></div></div><div class="muted-note" style="margin:16px 0"><strong class="quality-5">${ITEMS[r.reward].name}</strong><br>${r.text}<br>3.5% relic chance · guaranteed every 30 victories</div><div class="row between wrap"><small>${ITEMS[r.key].name}: <strong>${E.quantity(s,r.key)}</strong><br>100 key fragments can be crafted into a key.</small>${btn('Enter raid · 1 key','raid',`data-id="${r.id}"`,'primary',s.badges.length<r.badge||!E.quantity(s,r.key)||!!s.combat||s.trainer!=='combat')}</div></div></div>`).join('')}<div class="muted-note">Raids pause while the game is hidden or closed. Keys are consumed on entry. Stage two enemies hunt your least-defended companion. Guard and Interrupt share a 24-second cooldown; plan for the next attack.</div></div>`;}
function socialPage(){if(!Net.online.connected)return `${header('The trading post','A shared economy for your circle.')}<div class="panel empty"><span class="empty-icon">⚖</span><h2>Bring your journey online</h2><p>Sign in with email to connect a cloud save, trade supplies, and compare progress.</p>${btn('Connect account','account','','primary')}</div>`;return `${header('The trading post','Trade supplies. Compare journeys.',btn('Refresh','refresh-social','','subtle'))}<div class="split"><div class="stack"><div class="panel"><div class="panel-head"><h2>Marketplace</h2>${btn('List an item','list-dialog','','primary')}</div>${marketRows.length?marketRows.map(l=>`<div class="market-row"><div><strong>${esc(ITEMS[l.item]?.name||l.item)}</strong><small style="display:block">${fmt(l.count)} items · ${esc(l.sellerName)}</small></div><div style="text-align:right"><div class="gold" style="margin-bottom:7px">${fmt(l.price)}g total</div>${btn(l.seller===Net.online.user.uid?'Cancel':'Buy',l.seller===Net.online.user.uid?'market-cancel':'market-buy',`data-id="${l.id}"`,'subtle')}</div></div>`).join(''):'<div class="empty"><p>No open listings. Offer some supplies to your group.</p></div>'}</div>${btn('Collect sale proceeds','market-claim','','wide')}<div class="muted-note">Listing fee: 2% of total price, minimum 1 gold. Completed sales pay the seller 95%. Listings hold the actual supplies until purchased or cancelled. Crafted equipment and Ferals remain personal.</div></div><div class="panel" style="align-self:start"><div class="panel-head"><h2>Your circle</h2><small>By skill XP</small></div>${leaderRows.length?leaderRows.map((r,i)=>`<div class="leader-row"><strong class="gold">${i+1}</strong><div><strong>${esc(r.name)}</strong><small style="display:block">${r.champions} badges · ${r.collection} species · ${r.raids} raids</small></div><small>${short(r.skillXP)} XP</small></div>`).join(''):'<div class="empty"><p>Connect and save to publish your first score.</p></div>'}</div></div>`;}
function journalPage(){return `${header('The field journal','Rare encounters, meaningful drops, and the story of your team.')}<div class="stats-grid" style="margin-bottom:18px">${[[s.totals.kills,'Ferals defeated'],[s.totals.captures,'Captures'],[s.totals.crafts,'Items crafted'],[s.totals.gathered,'Resources']].map(([n,label])=>`<div class="stat-box"><strong>${short(n)}</strong><small>${label}</small></div>`).join('')}</div><div class="panel">${logHTML(160)}</div>`;}
function settingsPage(){return `${header('Make yourself at home',`Feralwild v${VERSION} · Save schema ${B.schema}`)}<div class="split"><div class="panel panel-pad stack"><h2>Your progress</h2><p>Local saves keep three generations. Export a backup before switching devices or clearing browser data.</p>${btn('Export save backup','export','','primary')}${btn('Cloud account & saves','account')}<label>Import a backup<input type="file" id="import-save" accept=".json"></label><small>Imports are validated before replacing progress. Your current save will be downloaded first.</small><hr class="divider"><h3>Presentation</h3><label class="row" style="display:flex"><input type="checkbox" id="motion-toggle" ${s.settings.motion?'checked':''}> Combat motion and effects</label><h3>Limited capture automation</h3><p style="font-size:.85rem">After six badges, a Warden seal permits one automatic attempt against a qualifying weakened Feral. Each attempt also consumes a snare, with 20% lower effectiveness.</p><label class="row" style="display:flex"><input type="checkbox" id="auto-capture" ${s.autoCapture?'checked':''} ${s.badges.length<6?'disabled':''}> Enable · trainer must be in combat</label><label>Minimum species rarity<select id="auto-rarity">${['Common','Uncommon','Rare','Apex'].map(r=>`<option ${r===s.autoRarity?'selected':''}>${r}</option>`).join('')}</select></label><small>Elemental and Titanblood Ferals always qualify. Warden seals owned: ${E.quantity(s,'autoseal')}.</small></div><div class="panel panel-pad stack"><h2>Field guide</h2><p><strong>Two jobs at once.</strong> Your team keeps hunting while your trainer gathers or crafts. Without the trainer, no food or captures are available.</p><p><strong>Care matters.</strong> At zero Morale, Attack, Defense, and Speed fall to 55%. Ferals still fight. Treats restore Morale; medicine restores incapacitated Ferals outside battle.</p><p><strong>Natural potential.</strong> IVs are permanent. Appraisal lenses reveal them. Titanblood multiplies rolled stats by 1.10. Bond grants up to 15% better treats and 10% slower Morale loss.</p><p><strong>Offline play.</strong> Up to 12 hours are simulated using the same combat and crafting rules. Ordinary idle combat never captures. Raids pause while away.</p><p><strong>Speed.</strong> Attack interval is 10 ÷ [1 + 9 × (Speed − 1) ÷ 49], with a one-second minimum. The combat triangle gives 18% advantage and 15% disadvantage.</p><p><strong>Long-term skills.</strong> Skills cap at 100. Low-tier timber, copper, herbs, fiber, and salvage remain ingredients in higher-tier recipes.</p><small>No IV upgrades. No permanent death. No paid advantages.</small></div></div>`;}
function detail(id){const f=s.ferals.find(f=>f.id===id);if(!f)return;const sp=SPECIES[f.species],st=E.stats(s,f),level=E.feralLevel(s,f);modal(sp.name,`<div class="detail-hero">${portrait(f.species)}<div><span class="rarity ${sp.rarity}">${sp.rarity} · ${sp.style}</span><h2>${sp.name} ${f.titan?'♛':''}</h2><small>Level ${level} / ${E.cap(s)}${f.element?' · '+f.element:''}</small>${f.titan?'<div class="badge gold">TITANBLOOD · +10% rolled stats</div>':''}<p style="font-size:.8rem">${f.hp<=0?'Incapacitated — needs restorative medicine':Math.ceil(f.hp)+' / '+st.hp+' HP'}</p></div></div><div class="stats-grid">${['hp','atk','def','speed'].map((k,i)=>`<div class="stat-box"><strong>${Math.round(st[k])}</strong><small>${['HP','Attack','Defense','Speed'][i]}</small><small style="display:block" class="${f.appraised&&f.iv[i]>=90?'gold':''}">${f.appraised?f.iv[i]+' IV':'IV hidden'}</small></div>`).join('')}</div><small>${st.interval.toFixed(2)}s attack interval · ${fmt(f.xp)} XP${level===E.cap(s)?' · badge level cap reached':''}</small><div><div class="row between"><small>Morale ${Math.round(f.morale)}%</small><small class="bond">♡ Bond ${Math.floor(f.bond/100)}% ${f.bond>=10000?'· SOULBOUND':''}</small></div>${bar(f.morale)}<small>Bond belongs to this individual. Its IVs will never change.</small></div><div class="muted-note"><strong>${sp.attack}</strong> · basic attack<br><strong>${ABILITIES[sp.ability].name}</strong> · ${ABILITIES[sp.ability].text}<br><strong>${PASSIVES[sp.passive].name}</strong> · ${PASSIVES[sp.passive].text}${f.element?'<br><strong>'+f.element+'</strong> · '+ELEMENTS[f.element].effect:''}</div><div class="toolbar">${btn(s.team.includes(f.id)?'Remove from team':'Add to team','team',`data-id="${id}"`,'primary',!!s.combat||!s.team.includes(id)&&s.team.length>=3)}${!f.appraised?btn('Appraise · 1 lens','use',`data-id="lens" data-feral="${id}"`,'',!E.quantity(s,'lens')):''}${btn('Care','care',`data-id="${id}"`)}</div><h3>Equipment</h3><div class="gear-slots">${['head','armor','weapon','accessory'].map(slot=>{const g=s.gear.find(g=>g.id===f.gear[slot]);return `<div class="gear-slot"><small>${slot}</small><strong class="quality-${g?.quality||1}">${g?ITEMS[g.item].name:'Unequipped'}</strong>${btn(g?'Change':'Equip','equip-picker',`data-feral="${id}" data-slot="${slot}"`,'subtle',!!s.combat)}${g?btn('Unequip','unequip',`data-feral="${id}" data-slot="${slot}"`,'subtle',!!s.combat):''}</div>`;}).join('')}</div>${!s.team.includes(id)?btn('Release into the wild','release-dialog',`data-id="${id}"`,'danger'):''}`);}
function care(id){const f=s.ferals.find(f=>f.id===id);modal('Care for '+SPECIES[f.species].name,`<p>${Math.ceil(f.hp)} / ${E.stats(s,f).hp} HP · ${Math.round(f.morale)}% Morale</p>${Object.entries(s.bag).filter(([id,n])=>n&&['food','treat','revive'].includes(ITEMS[id].type)).map(([item,n])=>`<div class="row between"><div><strong>${ITEMS[item].name}</strong><small style="display:block">${n} owned · ${ITEMS[item].morale?'+'+ITEMS[item].morale+' Morale':ITEMS[item].type==='revive'?'Revive at '+Math.round(ITEMS[item].heal*100)+'% HP':'Heal '+ITEMS[item].heal+' HP'}</small></div>${btn('Use','use',`data-id="${item}" data-feral="${id}"`)}</div>`).join('')||'<p>Craft food and treats in Cooking, or restorative medicine in Alchemy.</p>'}`);}
function speciesDetail(id){const sp=SPECIES[id];modal(sp.name,`<div class="detail-hero">${portrait(id)}<div><span class="rarity ${sp.rarity}">${sp.rarity} · ${sp.style}</span><h2>${sp.name}</h2><small>${AREAS[sp.area].name}</small></div></div><div class="stats-grid">${sp.base.map((v,i)=>`<div class="stat-box"><strong>${v}</strong><small>Base ${['HP','Attack','Defense','Speed'][i]}</small></div>`).join('')}</div><p><strong>${sp.attack}</strong> · basic attack<br><strong>${ABILITIES[sp.ability].name}</strong> · ${ABILITIES[sp.ability].text}<br><strong>${PASSIVES[sp.passive].name}</strong> · ${PASSIVES[sp.passive].text}</p><div class="muted-note">Drops: ${ITEMS[sp.drop].name}, ${ITEMS[['log','ore','fish','herb'][sp.special]+sp.area].name}, gold, and a very rare raid key chance.<br>Encounters: ${s.seen[id]||0} · Captures: ${s.caught[id]||0}<br>Rarity affects encounters and capture difficulty, never IV rolls.</div>`);}
function gearDetail(id){const g=s.gear.find(g=>g.id===id);if(!g)return;const item=ITEMS[g.item],wearer=s.ferals.find(f=>Object.values(f.gear).includes(id));modal(item.name,`<span class="quality-${g.quality}">${QUALITIES[g.quality]} · ${item.slot.toUpperCase()} · level ${item.level}</span><div class="stats-grid">${Object.entries(item.stats).map(([k,v])=>`<div class="stat-box"><strong>+${(v*B.qualityMultipliers[g.quality]).toFixed(1)}</strong><small>${k.toUpperCase()}</small></div>`).join('')}</div><p>${item.propertyText}</p><small>${wearer?'Equipped by '+SPECIES[wearer.species].name:'Not equipped'}</small><label>Equip on<select id="gear-target">${s.ferals.map(f=>`<option value="${f.id}">${SPECIES[f.species].name} · Lv. ${E.feralLevel(s,f)} · ${f.id}</option>`).join('')}</select></label>${btn('Equip','equip',`data-id="${id}"`,'primary',!!s.combat)}${btn('Salvage equipment','salvage-dialog',`data-id="${id}"`,'danger',!!wearer)}<small>Salvage returns ${1+Math.floor(g.quality/2)} tempered salvage${g.quality>=3?' and '+(g.quality-2)+' prismatic dust':''}. Equipped items cannot be salvaged.</small>`);}
let pendingCloud=null;
function account(){modal('Your cloud account',`<p>Connect your journey with email and password. Your local save stays available if you lose connection.</p>${Net.online.user?`<div class="muted-note">${esc(Net.online.user.email)}<br>${Net.online.connected?esc(Net.online.status):'Choose a save to finish connecting.'}</div><div class="toolbar">${btn('Save to cloud','cloud-save','','primary',!Net.online.connected)}${btn('Reconnect / load','cloud-read')}${btn('Sign out','logout','','subtle')}</div>`:`<form id="auth-form" class="stack"><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" minlength="6" autocomplete="current-password" required></label><div class="toolbar"><button class="primary" type="submit" name="mode" value="login">Sign in</button><button type="submit" name="mode" value="register">Create account</button></div>${btn('Reset password','reset-password','','subtle')}</form>`}<div id="online-error" role="status"></div><small>Cloud saves and trading need the included Firestore rules published in your Firebase Console.</small>`);}
function cloudChoice(data){pendingCloud=data;modal('Choose your progress',`<p>${data?'A cloud save exists. Choose carefully; these journeys are not merged.':'There is no cloud save for this account yet.'}</p>${data?`<div class="two"><div class="muted-note"><strong>This device</strong><br>${esc(s.name)}<br>${s.ferals.length} Ferals · ${s.badges.length} badges<br>${fmt(s.totals.kills)} defeats</div><div class="muted-note"><strong>Cloud</strong><br>${esc(data.state.name)}<br>${data.state.ferals.length} Ferals · ${data.state.badges.length} badges<br>${fmt(data.state.totals.kills)} defeats</div></div>${btn('Load cloud journey','cloud-load','','primary')}`:''}${btn(data?'Keep this device and replace cloud save':'Connect this journey to cloud','cloud-use-local','','',!s.started)}<small>A backup of the current local journey is downloaded before loading cloud progress. Replacing a cloud save requires a second confirmation.</small>`);}
async function networkTask(fn){if(cloudBusy||busy)return toast('An online operation is already running.');busy=true;try{await fn();}catch(e){const message=Net.friendlyError(e);if($('#online-error'))$('#online-error').textContent=message;else toast(message);console.error(e);}finally{busy=false;lastPerformance=performance.now();persist();}}
async function refreshSocial(){await Net.publishScore(s);[marketRows,leaderRows]=await Promise.all([Net.listings(),Net.scores()]);if(view==='social')render();}
async function market(action,params={}){await networkTask(async()=>{persist();s=await Net.marketAction(s,action,params);persist();$('#modal').close();await refreshSocial();render();toast('Trade completed.');});}
function research(){modal('Compendium research',`<p>Each species awards gold and an appraisal lens at 3, 10, and 25 captures. Different-species milestones also award five extra homes.</p>${[10,20,40,60,80,100].map(n=>`<div class="row between"><div><strong>${n} different species</strong><small style="display:block">${n*100}g · ${Math.max(1,n/10)} lenses · 5 homes</small></div>${btn(s.research.includes(n)?'Claimed':'Claim','research-claim',`data-id="${n}"`,'',s.research.includes(n)||Object.keys(s.caught).length<n)}</div>`).join('')}`);}
async function handle(action,d){if(action==='close')return $('#modal').close();if(action==='account')return account();if(tabLocked)return toast('Another tab is playing. Close it and reload here.');if(busy||cloudBusy)return toast('Finishing a cloud operation. Please wait.');let refresh=true;switch(action){
case 'starter':{s.name=$('#trainer-name')?.value||s.name;selectedStarter=Number(d.id);render();return;}
case 'begin':E.startGame(s,selectedStarter,$('#trainer-name')?.value);E.startCombat(s);window.scrollTo(0,0);break;
case 'nav':view=d.view;$('#modal').close();render();window.scrollTo(0,0);if(view==='social'&&Net.online.connected)await networkTask(refreshSocial);return;
case 'more':modal('Your journey',`<div class="stack">${nav.slice(4).map(([id,icon,name])=>btn(icon+' '+name,'nav',`data-view="${id}"`,'wide')).join('')}<small>Feralwild v${VERSION} · ${Net.online.connected?Net.online.status:'Saved on this device'}</small>`);return;
case 'join':s.trainer='combat';s.activity=null;toast('Trainer joined the team.');break;
case 'skill':skill=d.id;break;
case 'gather':if(!E.beginActivity(s,skill,Number(d.id)))toast('This activity is still locked.');else toast(SKILLS[skill].name+' started.');break;
case 'craft':if(!E.beginActivity(s,skill,d.id))toast('More materials, gold, or skill levels needed.');else toast('Crafting '+ITEMS[d.id].name+'.');break;
case 'hunt':if(!E.startCombat(s))toast('Restore a companion before hunting.');break;
case 'retreat':if(s.combat?.kind==='raid'){modal('Leave this raid?',`<p>The entry key has been spent. Leaving ends this attempt.</p>${btn('Leave raid','confirm-retreat','','danger')}`);return;}E.stopCombat(s);break;
case 'confirm-retreat':E.stopCombat(s);$('#modal').close();break;
case 'hold':s.hold=!s.hold;break;
case 'focus':if(s.combat)s.combat.focus=d.id;break;
case 'capture':{const result=E.capture(s,d.id);toast(result==='caught'?'A new companion joins you!':result==='escaped'?'It broke free. Try weakening it further.':s.ferals.length>=s.storage?'Your Feral homes are full.':'Capture needs the trainer, a snare, and a living target.');break;}
case 'command':if(!E.command(s,d.id))toast('Command unavailable or recovering.');break;
case 'champion':if(!E.startCombat(s,'champion'))toast('Finish all three requirements and retreat from any current fight.');break;
case 'donate':if(E.donate(s,Number(d.id)))toast('Donation accepted.');break;
case 'travel':if(!s.combat&&Number(d.id)<=s.badges.length){s.area=Number(d.id);view='battle';}break;
case 'raid':if(E.startCombat(s,'raid',Number(d.id)))view='battle';else toast('A key, the required badges, and your trainer are needed.');break;
case 'raid-choice':if(!E.raidChoice(s,d.id))toast('Not enough gold for restoration.');break;
case 'detail':detail(d.id);return;
case 'species':speciesDetail(Number(d.id));return;
case 'care':care(d.id);return;
case 'team':if(!E.addToTeam(s,d.id))toast('Retreat first. Keep 1–3 Ferals in your team.');detail(d.id);persist();render();return;
case 'use':if(!E.useItem(s,d.id,d.feral))toast('This item cannot help right now. Revive outside combat; food needs the trainer during battle.');else toast(ITEMS[d.id].name+' used.');detail(d.feral);persist();render();return;
case 'use-picker':modal('Use '+ITEMS[d.id].name,`<div class="stack">${s.ferals.map(f=>btn(`${SPECIES[f.species].name} · ${Math.ceil(f.hp)} HP · ${Math.round(f.morale)}% Morale`,'use',`data-id="${d.id}" data-feral="${f.id}"`,'wide')).join('')}</div>`);return;
case 'lure':if(E.useItem(s,d.id))toast('Hunting boost active for 30 minutes.');else toast('Join combat and wait for any active boost to finish.');break;
case 'bag-tab':bagTab=d.id;break;
case 'collection-mode':collectionMode=d.id;break;
case 'gear-detail':gearDetail(d.id);return;
case 'equip-picker':{const f=s.ferals.find(f=>f.id===d.feral);modal('Equip '+d.slot,`<div class="stack">${s.gear.filter(g=>ITEMS[g.item].slot===d.slot).map(g=>btn(`${QUALITIES[g.quality]} ${ITEMS[g.item].name} · Lv. ${ITEMS[g.item].level}`,'equip',`data-id="${g.id}" data-feral="${f.id}"`,'quality-'+g.quality,E.feralLevel(s,f)<ITEMS[g.item].level)).join('')||'<p>No equipment for this slot. Craft it in Smithing.</p>'}</div>`);return;}
case 'equip':{const id=d.feral||$('#gear-target')?.value;if(E.equip(s,id,d.id)){detail(id);toast('Equipment fitted.');}else toast('Retreat first and check the equipment level requirement.');persist();render();return;}
case 'unequip':{const f=s.ferals.find(f=>f.id===d.feral);if(!s.combat){delete f.gear[d.slot];f.hp=Math.min(f.hp,E.stats(s,f).hp);}detail(f.id);persist();render();return;}
case 'salvage-dialog':modal('Salvage this equipment?',`<p>The item will be dismantled permanently. Its salvage can be used in higher-tier recipes.</p>${btn('Confirm salvage','salvage',`data-id="${d.id}"`,'danger')}`);return;
case 'salvage':if(E.salvage(s,d.id)){toast('Materials recovered.');$('#modal').close();}else toast('Equipped gear cannot be salvaged.');break;
case 'release-dialog':{const f=s.ferals.find(f=>f.id===d.id);modal('Release '+SPECIES[f.species].name+'?',`<p>This permanently releases this individual, including its unique IVs${f.titan?' and Titanblood trait':''}. Remove its equipment first. Your capture research stays recorded.</p>${btn('Release permanently','release',`data-id="${d.id}"`,'danger')}`);return;}
case 'release':if(E.release(s,d.id)){$('#modal').close();toast('Returned to the wild.');}else toast('Remove the Feral from your team and unequip it first.');break;
case 'storage':{const cost=Math.floor(500*1.65**((s.storage-30)/10));modal('More room for companions',`<p>You have ${s.storage} homes. Add ten homes for ${fmt(cost)} gold.</p>${btn('Buy 10 homes','storage-buy','','primary',s.gold<cost||s.storage>=300)}`);return;}
case 'storage-buy':if(E.upgradeStorage(s)){$('#modal').close();toast('Ten new homes built.');}break;
case 'research':research();return;
case 'research-claim':E.researchClaim(s,Number(d.id));research();persist();render();return;
case 'sell-dialog':modal('Sell '+ITEMS[d.id].name,`<p>Shop value: ${ITEMS[d.id].value} gold each. Owned: ${E.quantity(s,d.id)}.</p><label>Quantity<input id="sell-count" type="number" min="1" max="${E.quantity(s,d.id)}" value="1" inputmode="numeric"></label>${btn('Sell to shop','sell',`data-id="${d.id}"`,'primary')}`);return;
case 'sell':{const n=Number($('#sell-count').value);if(Number.isSafeInteger(n)&&n>0&&n<=E.quantity(s,d.id)){E.add(s,d.id,-n);s.gold+=ITEMS[d.id].value*n;$('#modal').close();toast('Sold for '+fmt(ITEMS[d.id].value*n)+' gold.');}else toast('Enter an available whole quantity.');break;}
case 'export':Saves.exportSave(s);return;
case 'logout':await networkTask(async()=>{await Net.logout();account();render();});return;
case 'reset-password':await networkTask(async()=>{const email=$('#auth-form input[name=email]')?.value;if(!email)throw Error('Enter your email first.');await Net.resetPassword(email);$('#online-error').textContent='If that account exists, a reset email has been requested.';});return;
case 'cloud-read':await networkTask(async()=>cloudChoice(await Net.readCloud()));return;
case 'cloud-load':await networkTask(async()=>{if(!pendingCloud)return;Saves.exportSave(s);s=E.clone(pendingCloud.state);catchUp();Net.acceptCloud();pendingCloud=null;$('#modal').close();render();toast('Cloud journey loaded.');});return;
case 'cloud-use-local':if(pendingCloud){modal('Replace the cloud journey?',`<p>This replaces the cloud journey with this device’s progress. The existing cloud journey will be downloaded as a backup first.</p>${btn('Back up and replace cloud','cloud-replace','','danger')}`);return;}await networkTask(async()=>{Net.acceptCloud();await Net.pushCloud(s);await Net.publishScore(s);$('#modal').close();render();toast('Cloud save connected.');});return;
case 'cloud-replace':await networkTask(async()=>{if(pendingCloud)Saves.exportSave(pendingCloud.state);Net.acceptCloud();await Net.pushCloud(s);pendingCloud=null;$('#modal').close();render();toast('Cloud updated.');});return;
case 'cloud-save':await networkTask(async()=>{persist();await Net.pushCloud(s);await Net.publishScore(s);account();toast('Cloud saved.');});return;
case 'refresh-social':await networkTask(refreshSocial);return;
case 'list-dialog':modal('Offer supplies',`<p>Choose a total price for the entire stack. A 2% listing fee is paid now.</p><label>Item<select id="list-item">${Object.entries(s.bag).filter(([id,n])=>n&&['material','food','treat','revive','snare','appraise','lure','automation'].includes(ITEMS[id].type)).map(([id,n])=>`<option value="${id}">${ITEMS[id].name} (${n})</option>`).join('')}</select></label><div class="two"><label>Quantity<input id="list-count" type="number" min="1" value="1" inputmode="numeric"></label><label>Total gold price<input id="list-price" type="number" min="1" value="10" inputmode="numeric"></label></div>${btn('Create listing','market-list','','primary')}`);return;
case 'market-list':await market('list',{item:$('#list-item').value,count:Number($('#list-count').value),price:Number($('#list-price').value)});return;
case 'market-buy':{const l=marketRows.find(l=>l.id===d.id);modal('Buy this listing?',`<p>${l.count} ${esc(ITEMS[l.item]?.name)} for ${fmt(l.price)} gold total.</p>${btn('Confirm purchase','market-confirm',`data-id="${l.id}"`,'primary')}`);return;}
case 'market-confirm':await market('buy',{id:d.id});return;
case 'market-cancel':await market('cancel',{id:d.id});return;
case 'market-claim':await market('claim');return;
default:refresh=false;
}if(refresh){persist();render();}}
function updateLive(){if(!s?.started)return;$$('[data-gold]').forEach(el=>el.textContent=short(s.gold));$$('[data-count]').forEach(el=>el.textContent=fmt(E.quantity(s,el.dataset.count)));$$('[data-cost]').forEach(el=>{const n=E.quantity(s,el.dataset.cost),need=Number(el.dataset.need);el.textContent=fmt(n)+'/'+need;el.style.color=n>=need?'var(--green)':'var(--red)';});$$('[data-skill-level]').forEach(el=>el.textContent=E.lv(s,el.dataset.skillLevel));const a=s.activity;if(a&&$('#activity-progress')){const total=a.recipe?RECIPES.find(r=>r.id===a.recipe).seconds:5+a.tier*.6;$('#activity-progress').style.width=(a.progress/total*100)+'%';if($('#activity-countdown'))$('#activity-countdown').textContent=Math.max(0,total-a.progress).toFixed(1)+'s';}if(view==='skills'){const l=E.lv(s,skill),xp=s.skills[skill];if($('#skill-level'))$('#skill-level').textContent='LV. '+l;if($('#skill-xp'))$('#skill-xp').textContent=fmt(xp)+' / '+(l===100?'MAX':fmt(skillXP(l+1)))+' XP';if($('#skill-progress'))$('#skill-progress').style.width=(l===100?100:(xp-skillXP(l))/(skillXP(l+1)-skillXP(l))*100)+'%';$$('[data-recipe]').forEach(el=>{const r=RECIPES.find(r=>r.id===el.dataset.recipe);el.disabled=E.lv(s,r.skill)<r.level||r.tier>s.badges.length||!E.canCraft(s,r);});}
 if(view!=='battle')return;for(const f of [...E.ownedTeam(s),...(s.combat?.enemies||[])]){const st=E.stats(s,f),card=$(`[data-fighter="${f.id}"]`);if(!card)continue;card.classList.toggle('down',f.hp<=0);const hp=$(`[data-hp="${f.id}"]`);if(hp)hp.textContent=Math.ceil(f.hp)+' / '+st.hp;const health=$(`[data-health="${f.id}"]`);if(health)health.style.width=f.hp/st.hp*100+'%';const timer=$(`[data-timer="${f.id}"]`);if(timer)timer.style.width=Math.min(100,f.timer/st.interval*100)+'%';const status=$(`[data-status="${f.id}"]`);if(status)status.textContent=Object.entries(f.status).filter(([,v])=>v>0).map(([k])=>k).join(' · ')||ABILITIES[SPECIES[f.species].ability].name+' · '+Math.ceil(f.cooldown)+'s';const capture=$(`[data-capture="${f.id}"]`);if(capture){capture.textContent=s.captureTimer>0?'Recovering '+s.captureTimer.toFixed(1)+'s':'Snare · '+Math.round(E.captureChance(s,f)*100)+'%';capture.disabled=s.trainer!=='combat'||f.hp<=0||!E.quantity(s,s.snare)||s.captureTimer>0;}}
 if($('#raid-warning'))$('#raid-warning').innerHTML=s.combat?.cast>0?`<div class="battle-notice">DEVASTATING ATTACK · ${s.combat.cast.toFixed(1)}s · Interrupt or guard!</div>`:'';
}
function effects(events){if(view!=='battle')return;for(const e of events){const card=$(`[data-fighter="${e.target}"]`);if(!card)continue;const layer=card.querySelector('.hit-layer');if(layer.childElementCount>5)layer.firstChild.remove();const el=document.createElement('span');el.className='hitsplat '+e.kind;el.textContent=(e.kind==='heal'?'+':'')+e.value+(e.kind==='crit'?'!':'');el.style.marginLeft=(Math.random()*16-8)+'px';layer.append(el);setTimeout(()=>el.remove(),1100);if(['damage','crit','dot'].includes(e.kind)){card.classList.remove('struck');void card.offsetWidth;card.classList.add('struck');}if(e.source){const source=$(`[data-fighter="${e.source}"]`);if(source){source.classList.remove('attacking');void source.offsetWidth;source.classList.add('attacking');}}}}
function signature(){return [s.combat?.kind,s.combat?.enemies.map(f=>f.id).join(','),s.combat?.awaiting,s.combat?.stage,s.trainer,s.activity?.recipe,s.activity?.tier,E.lv(s,skill),s.badges.length,E.tasks(s,AREAS[s.area]).map(t=>t.done).join(','),s.team.join(',')].join('|');}
function catchUp(){const elapsed=Math.max(0,(Date.now()-s.lastWall)/1000);if(elapsed<3)return null;if(s.combat?.kind==='raid')E.log(s,'Raid paused while you were away.');const report=E.advance(s,elapsed,true);s.lastWall=Date.now();s.clock=s.lastWall;return report;}
function awayModal(r){if(!r||r.seconds<30)return;modal('Welcome back, '+esc(s.name),`<span class="eyebrow">${duration(r.seconds)} of offline progress</span><div class="stats-grid">${[[r.kills,'Defeated'],[r.gathered,'Gathered'],[r.crafts,'Crafted'],[r.gold,'Gold']].map(([v,n])=>`<div class="stat-box"><strong>${short(v)}</strong><small>${n}</small></div>`).join('')}</div>${r.captures?`<p>${r.captures} automated captures used Warden seals and snares.</p>`:''}<p>${s.trainer==='combat'?'Your trainer stayed with the team.':'Your trainer worked while your team fought independently.'} Rare encounters are recorded in your journal.</p><small>Offline progress is capped at 12 hours. Raids pause while away.</small>${btn('Continue the journey','close','','primary')}`);}
function loop(now){requestAnimationFrame(loop);if(!s?.started||tabLocked||busy||cloudBusy||document.hidden){lastPerformance=now;return;}let elapsed=(now-lastPerformance)/1000;lastPerformance=now;if(elapsed>3){const report=catchUp();render();awayModal(report);return;}accumulator+=Math.min(elapsed,3);const before=signature(),events=[];while(accumulator>=B.step){E.step(s,B.step,events);accumulator-=B.step;}if(before!==signature()&&!(document.activeElement instanceof HTMLSelectElement))render();if(now-(loop.lastUI||0)>=200){updateLive();loop.lastUI=now;}effects(events);lastSave+=elapsed;lastRender+=elapsed;cloudElapsed+=elapsed;
 if(lastRender>=4){lastRender=0;if(view==='battle'&&$('#recent-log'))$('#recent-log').innerHTML=logHTML(5);}
 if(lastSave>=B.saveSeconds){lastSave=0;persist();}
 if(cloudElapsed>=90&&Net.online.connected){cloudElapsed=0;cloudBusy=true;persist();Net.pushCloud(s).catch(e=>{Net.online.connected=false;Net.online.status='Cloud needs reconnect';toast(Net.friendlyError(e));}).finally(()=>{cloudBusy=false;lastPerformance=performance.now();});}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;handle(el.dataset.action,el.dataset).catch(error=>{console.error(error);toast(error.message||'Action could not be completed.');});});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.portrait[data-action]')){e.preventDefault();handle(e.target.dataset.action,e.target.dataset);}});
document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const form=new FormData(e.target),register=e.submitter?.value==='register';await networkTask(async()=>cloudChoice(await Net.login(String(form.get('email')),String(form.get('password')),register)));});
document.addEventListener('change',async e=>{if(e.target.id==='import-save'){const file=e.target.files?.[0];if(!file)return;try{const imported=Saves.decode(await file.text());modal('Restore this backup?',`<p>${esc(imported.name)} · ${imported.ferals.length} Ferals · ${imported.badges.length} badges.</p><p>Your current save will be downloaded before replacement. Cloud syncing will disconnect until you choose a save again.</p><button id="confirm-import" class="primary">Back up current save and restore</button>`);$('#confirm-import').onclick=()=>{if(s)Saves.exportSave(s);s=imported;Net.online.connected=false;const report=catchUp();persist();$('#modal').close();render();awayModal(report);};}catch(error){toast(error.message);}return;}if(!s||tabLocked||busy)return;const id=e.target.id;if(id==='snare-select')s.snare=e.target.value;if(id==='food-select')s.food=e.target.value;if(id==='auto-eat')s.autoEat=e.target.checked;if(id==='motion-toggle'){s.settings.motion=e.target.checked;document.body.classList.toggle('no-motion',!s.settings.motion);}if(id==='auto-capture')s.autoCapture=e.target.checked&&s.badges.length>=6;if(id==='auto-rarity')s.autoRarity=e.target.value;if(id==='collection-area'){collectionArea=e.target.value;render();}persist();});
document.addEventListener('visibilitychange',()=>{if(!s||tabLocked)return;if(document.hidden)persist();else{const report=catchUp();persist();lastPerformance=performance.now();render();awayModal(report);}});
window.addEventListener('pagehide',persist);
async function boot(){if(navigator.locks){tabLocked=true;await navigator.locks.request('feralwild-active-game',{ifAvailable:true},async lock=>{if(!lock){render();modal('Already playing in another tab','<p>To protect your progress, only one tab can run this journey. Close the other Feralwild tab, then reload this one.</p>');return;}tabLocked=false;startRuntime();await new Promise(()=>{});});}else{startRuntime();window.addEventListener('storage',e=>{if(e.key===Saves.saveKey){tabLocked=true;modal('Another tab changed your save','<p>This tab has paused to protect your progress. Close it and continue in the other tab.</p>');}});}}
function startRuntime(){if(navigator.onLine)Net.connect().then(()=>{if(Net.online.user&&s?.started&&!$('#modal').open)render();}).catch(()=>{});const report=s?.started?catchUp():null;render();if(loaded.recovered)toast('Recovered your previous valid save. Export a backup now.');awayModal(report);persist();requestAnimationFrame(loop);}
boot();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
